# convex hull test
def side(a,b,p): return (b[0]-a[0])*(p[1]-a[1])-(b[1]-a[1])*(p[0]-a[0])
def in_hull(p,pts):
    if len(pts)<3: return p in pts
    # andrew monotone chain, then point-in-polygon incl boundary
    P=sorted(set(pts))
    def cross(o,a,b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
    lower=[]
    for pt in P:
        while len(lower)>=2 and cross(lower[-2],lower[-1],pt)<=0: lower.pop()
        lower.append(pt)
    upper=[]
    for pt in reversed(P):
        while len(upper)>=2 and cross(upper[-2],upper[-1],pt)<=0: upper.pop()
        upper.append(pt)
    poly=lower[:-1]+upper[:-1]
    # point in polygon (boundary counts)
    n=len(poly); inside=False
    for k in range(n):
        a,b=poly[k],poly[(k+1)%n]
        if side(a,b,p)==0 and min(a[0],b[0])<=p[0]<=max(a[0],b[0]) and min(a[1],b[1])<=p[1]<=max(a[1],b[1]): return True
    for k in range(n):
        a,b=poly[k],poly[(k+1)%n]
        if (a[1]>p[1])!=(b[1]>p[1]) and p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0]: inside=not inside
    return inside
