def fill_between(grid, marker, fill):
    """Between each consecutive pair of marker cells in a row or column, recolor the cells strictly between them to fill; markers and other cells stay."""
    out=[r[:] for r in grid]; h,w=len(grid),len(grid[0])
    for row in out:
        pos=[j for j,v in enumerate(row) if v==marker]
        for a,b in zip(pos,pos[1:]):
            for j in range(a+1,b): row[j]=fill
    for j in range(w):
        pos=[i for i in range(h) if out[i][j]==marker]
        for a,b in zip(pos,pos[1:]):
            for i in range(a+1,b): out[i][j]=fill
    return out

def background(grid):
    """The most common color in the grid."""
    from collections import Counter
    return Counter(v for r in grid for v in r).most_common(1)[0][0]

